return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'brx','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:26+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s ब्लक टैगनि "%1$s" एट्रिबिउटखौ दाबब्ला दं मानोना ब्लकआ बे ID जों मोनसे फील्डखौ फोसावाखै। फील्डखौ फोसाव, एबा बेखौ data-, aria- एबा html- एट्रिबिउट बादि लिरनो, जाहाथे बेखौ रुट एलिमेन्टाव होयो।','This storage key is not declared by the block or its extensions.'=>'बे स्टरेज कि-बो ब्लक एबा बेनि एक्सटेन्सनफोरा फोसावाखै।','This top-level key is not an attribute of the block, so it is ignored.'=>'बे top-level key आ ब्लकनि attribute नङा, बेखायनो बेखौ इग्नोर खालामो।','This key is only read inside the blockstudio object, which is missing.'=>'बे key खौल\' blockstudio object नि सिङावनो फरायो, जाय गैया।','This value is not among the field options.'=>'बे बेसेदआ फील्डनि अप्सनफोरनि गेजेराव गैया।','This value has an unsupported shape for the field.'=>'बे बेसेदनि आकारआ फील्डनि थाखाय बाहायजाथाव नङा।','This repeater has fewer rows than its minimum.'=>'बे रिपिटारआनि रोफोरआ खमजाथार।','This repeater has more rows than its maximum.'=>'बे रिपिटारआनि रोफोरआ बांसिनजाथार।','This storage key has conflicting field definitions.'=>'बे स्टरेज कि-आव फील्डनि बिबुंथिफोरा मोनसे जाथाव नङा।','The nested field value overrides this top-level value.'=>'नेस्टेड फील्डनि बेसेदआ बे टप-लेभेल बेसेदखौ ओभरराइड खालामो।','Extension bindings read this value only from blockstudio.attributes.'=>'एक्सटेन्सन बाइन्डिंगफोरा बे बेसेदखौ blockstudio.attributes निफ्रायनो लायो।','Blockstudio field values must be stored in an object.'=>'Blockstudio फील्डनि बेसेदफोरखौ मोनसे अब्जेक्टआव दोननांगोन।','Blockstudio is preparing its block cache. Please retry shortly.'=>'Blockstudio आ ब्लक केशखौ थियारि खालामगासिनो दं। अनन